#include <algorithm>
#include <fstream>
int main() {
    std::ifstream in("pails.in");
    std::ofstream out("pails.out");
    int x, y, capacity;
    in >> x >> y >> capacity;
    int best = 0;
    for (int first = 0; first <= capacity / x; ++first) {
        const int remaining = capacity - first * x;
        const int second = remaining / y;
        best = std::max(best, first * x + second * y);
    }
    out << best << '\n';
}
