#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("cbarn.in");
    std::ofstream out("cbarn.out");
    int n;
    in >> n;
    std::vector<long long> rooms(n);
    long long total = 0, cost = 0;
    for (int i = 0; i < n; ++i) {
        in >> rooms[i];
        total += rooms[i];
        cost += static_cast<long long>(i) * rooms[i];
    }
    long long best = cost;
    for (int entrance = 0; entrance < n; ++entrance) {
        best = std::min(best, cost);
        cost += static_cast<long long>(n) * rooms[entrance] - total;
    }
    out << best << '\n';
}
