#include <algorithm>
#include <array>
#include <fstream>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("balancing.in");
    std::ofstream out("balancing.out");
    int n, bound;
    in >> n >> bound;
    std::vector<std::pair<int, int>> points(n);
    std::vector<int> xs{0}, ys{0};
    for (auto &[x, y] : points) {
        in >> x >> y;
        xs.push_back(x + 1);
        ys.push_back(y + 1);
    }
    std::sort(xs.begin(), xs.end());
    xs.erase(std::unique(xs.begin(), xs.end()), xs.end());
    std::sort(ys.begin(), ys.end());
    ys.erase(std::unique(ys.begin(), ys.end()), ys.end());
    int best = n;
    for (int a : xs) {
        for (int b : ys) {
            std::array<int, 4> count{};
            for (const auto &[x, y] : points) ++count[2 * (x > a) + (y > b)];
            best = std::min(best, *std::max_element(count.begin(), count.end()));
        }
    }
    out << best << '\n';
}
